import React, { useState, useCallback } from 'react';
import {
  JxPage,
  JxHeader,
  JxBadge,
  JxSection,
  JxSegmentedControl,
  JxSegmentedItem,
  JxSlider,
  JxSwitch,
  JxDivider,
  JxSelect,
  JxSelectOption,
  JxFormRow,
} from '@jinx-ui/react';

type Theme = 'light' | 'dark' | 'system';
type Font = 'default' | 'rounded' | 'mono';

interface AppearanceSettings {
  theme: Theme;
  scale: number;
  dense: boolean;
  font: Font;
}

interface AppearanceScreenProps {
  onChange?: (settings: AppearanceSettings) => void;
}

const THEME_LABELS: Record<Theme, string> = {
  light: 'Светлая',
  dark: 'Тёмная',
  system: 'Системная',
};

const AppearanceScreen: React.FC<AppearanceScreenProps> = ({ onChange }) => {
  const [theme, setTheme] = useState<Theme>('system');
  const [scale, setScale] = useState<number>(100);
  const [dense, setDense] = useState<boolean>(false);
  const [font, setFont] = useState<Font>('default');

  const emit = useCallback(
    (next: Partial<AppearanceSettings>) => {
      onChange?.({
        theme,
        scale,
        dense,
        font,
        ...next,
      });
    },
    [theme, scale, dense, font, onChange]
  );

  const handleThemeChange = (value: Theme) => {
    setTheme(value);
    emit({ theme: value });
  };

  const handleScaleChange = (value: number) => {
    setScale(value);
    emit({ scale: value });
  };

  const handleDenseChange = (value: boolean) => {
    setDense(value);
    emit({ dense: value });
  };

  const handleFontChange = (value: Font) => {
    setFont(value);
    emit({ font: value });
  };

  return (
    <JxPage>
      <JxHeader
        title="Внешний вид"
        actions={
          <JxBadge variant="neutral" style={{ color: 'var(--jx-color-text-secondary)' }}>
            {THEME_LABELS[theme]}
          </JxBadge>
        }
      />

      <JxSection title="Тема оформления">
        <JxSegmentedControl
          value={theme}
          onChange={(value) => handleThemeChange(value as Theme)}
        >
          <JxSegmentedItem value="light">Светлая</JxSegmentedItem>
          <JxSegmentedItem value="dark">Тёмная</JxSegmentedItem>
          <JxSegmentedItem value="system">Системная</JxSegmentedItem>
        </JxSegmentedControl>
      </JxSection>

      <JxSection title="Масштаб интерфейса">
        <JxFormRow
          label="Масштаб"
          description="Изменяет размер элементов интерфейса"
          value={`${scale}%`}
        >
          <JxSlider
            min={80}
            max={140}
            step={5}
            value={scale}
            onChange={handleScaleChange}
            aria-label="Масштаб интерфейса"
          />
        </JxFormRow>
      </JxSection>

      <JxSection title="Плотность">
        <JxFormRow
          label="Плотная вёрстка"
          description="Уменьшает отступы между элементами"
        >
          <JxSwitch
            checked={dense}
            onChange={(e) => handleDenseChange(e.target.checked)}
            aria-label="Плотная вёрстка"
          />
        </JxFormRow>
      </JxSection>

      <JxDivider />

      <JxSection title="Ещё">
        <JxFormRow label="Шрифт" description="Используется во всём интерфейсе">
          <JxSelect
            value={font}
            onChange={(value) => handleFontChange(value as Font)}
            aria-label="Шрифт"
          >
            <JxSelectOption value="default">Стандартный</JxSelectOption>
            <JxSelectOption value="rounded">Скруглённый</JxSelectOption>
            <JxSelectOption value="mono">Моноширинный</JxSelectOption>
          </JxSelect>
        </JxFormRow>
      </JxSection>
    </JxPage>
  );
};

export default AppearanceScreen;

